const products=[{name:'GeForce RTX 4070',category:'Tarjetas de video',price:649990,detail:'12 GB · GDDR6X · Edición de referencia',type:'gpu',tag:'MÁS FPS. MÁS VICTORIAS.',description:'Más cuadros. Más detalle. Más posibilidades.<br>Desbloquea el potencial de tu próximo setup.'},{name:'Silla gamer Phantom',category:'Sillas',price:189990,detail:'Diseño ergonómico · Negro / verde',type:'chair',tag:'COMODIDAD PARA CADA PARTIDA',description:'Tu lugar en cada partida.<br>Dale a tu setup el asiento que merece.'},{name:'Ryzen 7 7800X3D',category:'Procesadores',price:399990,detail:'Procesador gamer · Modelo de referencia',type:'cpu',tag:'POTENCIA EN CADA JUGADA',description:'El corazón de tu próxima build.<br>Lleva tu experiencia de juego más allá.'},{name:'ROG Strix B650',category:'Tarjetas madres',price:249990,detail:'Placa madre · Modelo de referencia',type:'board',tag:'UNA BASE PARA IR MÁS LEJOS',description:'Cada gran setup comienza desde su base.<br>Conecta tu próxima evolución.'},{name:'Teclado Nova RGB',category:'Periféricos',price:69990,detail:'Formato compacto · Iluminación RGB',type:'keyboard',tag:'CADA TECLA CUENTA',description:'Precisión que se siente en cada movimiento.<br>Completa tu espacio de juego.'}];
const money=n=>'$'+n.toLocaleString('es-CL');const wa=p=>'https://wa.me/56966274175?text='+encodeURIComponent('Hola Fusionia, quiero consultar por '+p.name+' (precio de demostración '+money(p.price)+').');
function art(type){let shapes='';if(type==='gpu'){shapes=`<path d="M55 113L385 65 463 112 447 226 117 264 45 214Z" fill="#171c18" stroke="#626b58" stroke-width="2"/><path d="M55 113L385 65 463 112 130 163Z" fill="#353d30"/><path d="M130 163L463 112 447 226 117 264Z" fill="url(#metal)" stroke="#48553b"/><path d="M138 173L452 124" stroke="#c4ff45" stroke-width="4"/><path d="M62 125L113 169 102 239 53 207Z" fill="#222b20"/><path d="M141 253L425 220" stroke="#c4ff45" stroke-width="3"/><text x="242" y="109" fill="#c9d5bd" font-size="13" transform="rotate(-8 242 109)" font-family="monospace">GEFORCE RTX</text>`;[190,290,390].forEach((x,i)=>{const y=211-i*14;shapes+=`<g transform="translate(${x} ${y}) skewY(-8)"><ellipse rx="43" ry="38" fill="#090d0b" stroke="#535e48" stroke-width="3"/>${Array.from({length:9},(_,j)=>`<path d="M0-8Q9-35 27-22L14-5Z" fill="#333e32" stroke="#4b5743" stroke-width=".6" transform="rotate(${j*40})"/>`).join('')}<circle r="12" fill="#6a795a"/><circle r="7" fill="#1d2718"/></g>`})}if(type==='cpu'){shapes='<g transform="translate(250 165) rotate(-18)"><rect x="-106" y="-106" width="212" height="212" rx="5" fill="#344436" stroke="#748766" stroke-width="4"/><rect x="-88" y="-88" width="176" height="176" rx="12" fill="url(#silver)" stroke="#c5cfbb" stroke-width="3"/><text text-anchor="middle" y="-13" font-size="15" fill="#40493e" font-family="sans-serif">AMD</text><text text-anchor="middle" y="27" font-size="33" fill="#303b2c" font-family="sans-serif" font-weight="bold">RYZEN</text><text text-anchor="middle" y="53" font-size="10" fill="#53604d">7 / 7800X3D</text></g>'}if(type==='board'){shapes='<g transform="translate(155 40) rotate(12 100 120)"><rect width="200" height="255" rx="4" fill="#17231e" stroke="#77836b" stroke-width="2"/>';for(let i=0;i<12;i++)shapes+=`<path d="M${20+i*14} 20v${90+i*6}h40v50" fill="none" stroke="#819b4b" stroke-width=".7"/>`;shapes+='<rect x="60" y="60" width="77" height="80" fill="#707d67"/><rect x="70" y="70" width="57" height="60" fill="#222d23" stroke="#b9c8a8"/><path d="M10 12h40v120H10zM10 151h145v18H10zM30 190h145v15H30z" fill="#414a3e" stroke="#6c7c57"/><path d="M155 30v150m15-150v150m15-150v150" stroke="#c4ff45" stroke-width="7"/><path d="M80 224h110" stroke="#c4ff45" stroke-width="5"/></g>'}if(type==='chair'){shapes='<path d="M215 232v48m0-12-65 20m65-20 65 20m-65-20v30" stroke="#59644e" stroke-width="11"/><path d="M169 156h106l26 72q-70 32-156 0Z" fill="#252c23" stroke="#778269" stroke-width="3"/><path d="M170 171L158 66 181 26h69l24 40-10 110Z" fill="url(#metal)" stroke="#6f7f5c" stroke-width="3"/><path d="M179 39l-8 27 14 97m58-124 16 30-13 93" fill="none" stroke="#c4ff45" stroke-width="7"/><path d="M190 58h38v20h-38z" fill="#080d08"/><path d="M145 185l-20-7v-27h31m125 34 25-7v-27h-29" fill="none" stroke="#5f6c53" stroke-width="9"/><path d="M169 220q47 17 102 0" fill="none" stroke="#c4ff45" stroke-width="4"/>'}if(type==='keyboard'){shapes='<g transform="translate(57 115) rotate(-10 190 60)"><path d="M0 0h385l20 112H-15Z" fill="#252e25" stroke="#71815c" stroke-width="3"/><path d="M-10 106h410" stroke="#c4ff45" stroke-width="4"/>';for(let r=0;r<5;r++)for(let c=0;c<14;c++)shapes+=`<rect x="${8+c*26}" y="${7+r*18}" width="22" height="14" rx="2" fill="#111a15" stroke="${['#c4ff45','#59bca3','#a6a9ee'][Math.floor(c/5)]}" stroke-width=".8"/>`;shapes+='</g>'}return `<svg class="hardware" viewBox="0 0 500 330" role="img" aria-label="Ilustración referencial de ${type==='gpu'?'tarjeta gráfica':type==='chair'?'silla gamer':type==='cpu'?'procesador':type==='board'?'tarjeta madre':'teclado'}"><defs><linearGradient id="metal" x2=".3" y2="1"><stop stop-color="#56614c"/><stop offset=".5" stop-color="#242d23"/><stop offset="1" stop-color="#101711"/></linearGradient><linearGradient id="silver" x2="1" y2="1"><stop stop-color="#d8dfd3"/><stop offset=".5" stop-color="#899581"/><stop offset="1" stop-color="#c1cab9"/></linearGradient></defs>${shapes}</svg>`}
const track=document.getElementById('product-track'),stage=document.getElementById('scroll-stage');let selected='Todos',slide=0,timer;const cats=['Todos','Sillas','Procesadores','Tarjetas madres','Tarjetas de video','Periféricos'];document.getElementById('categorias').innerHTML=cats.map((c,i)=>`<button class="${i===0?'active':''}" data-category="${c}">${c}</button>`).join('');
function render(){track.innerHTML=products.filter(p=>selected==='Todos'||p.category===selected).map(p=>`<article class="product-card"><div class="card-top"><b>UPGRADE / ${String(products.indexOf(p)+1).padStart(2,'0')}</b><span>DEMO</span></div><div class="card-art">${art(p.type)}</div><div class="card-info"><span>${p.category.toUpperCase()}</span><h3>${p.name}</h3><p>${p.detail}</p><div class="card-price"><strong>${money(p.price)}</strong><a href="${wa(p)}" target="_blank" rel="noopener" aria-label="Consultar por ${p.name}">↗</a></div><button type="button" class="add-to-cart" data-add-product="${p.type}" aria-label="Agregar ${p.name} al carrito">Agregar al carrito <span>+</span></button></div></article>`).join('');resize();}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{selected=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));render()});
function resize(){const extra=Math.max(0,track.scrollWidth-track.parentElement.clientWidth);stage.style.height=extra?extra+track.offsetHeight+130+'px':'auto';updateScroll()}
function updateScroll(){const extra=Math.max(0,track.scrollWidth-track.parentElement.clientWidth);const progress=Math.min(1,Math.max(0,(20-stage.getBoundingClientRect().top)/(stage.offsetHeight-track.offsetHeight-40||1)));track.style.transform=`translateX(${-extra*(1-progress)}px)`}
window.addEventListener('scroll',updateScroll,{passive:true});window.addEventListener('resize',resize);document.getElementById('dots').innerHTML=products.map((p,i)=>`<button aria-label="Ver ${p.name}" data-slide="${i}"></button>`).join('');
function show(n){slide=(n+5)%5;const p=products[slide];document.getElementById('hero-art').innerHTML=art(p.type);document.getElementById('hero-name').textContent=p.name;document.getElementById('hero-category').textContent=p.category.toUpperCase();document.getElementById('hero-price').textContent=money(p.price);document.getElementById('hero-description').innerHTML=p.description;document.getElementById('spec-one').textContent=p.tag;const buy=document.getElementById('hero-buy');buy.dataset.addProduct=p.type;buy.setAttribute('aria-label','Agregar '+p.name+' al carrito');document.getElementById('slide-number').textContent=String(slide+1).padStart(2,'0');document.querySelectorAll('[data-slide]').forEach((d,i)=>d.classList.toggle('active',i===slide))}
function restart(){clearInterval(timer);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>show(slide+1),1000)}document.getElementById('previous').onclick=()=>{show(slide-1);restart()};document.getElementById('next').onclick=()=>{show(slide+1);restart()};document.querySelectorAll('[data-slide]').forEach(d=>d.onclick=()=>{show(+d.dataset.slide);restart()});document.querySelector('.hero').addEventListener('mouseenter',()=>clearInterval(timer));document.querySelector('.hero').addEventListener('mouseleave',restart);document.querySelector('.hero').addEventListener('focusin',()=>clearInterval(timer));document.addEventListener('visibilitychange',()=>document.hidden?clearInterval(timer):restart());show(0);render();restart();
